std::string hx(const unsigned char*p,size_t n){static const char*d="0123456789abcdef";std::string s;s.reserve(2*n);for(size_t i=0;i<n;i++){s+=d[p[i]>>4];s+=d[p[i]&15];}return s;}
std::string hx(const std::string&s){return hx((const unsigned char*)s.data(),s.size());}
std::string unhx(const std::string&s){if(s=="-")return "";need(s.size()<=65536&&s.size()%2==0&&s.find_first_not_of("0123456789abcdef")==s.npos,"state/path hex","INVALID-CHECKPOINT");std::string x;for(size_t i=0;i<s.size();i+=2)x+=char(std::stoul(s.substr(i,2),nullptr,16));return x;}
struct Saved {Parser parser;SHA256_CTX sha;U offset=0;size_t peak=0;std::string pending;Saved(const Index&i):parser(i){SHA256_Init(&sha);}
 void load(const std::string&hex){if(hex=="-")return;std::istringstream f(unhx(hex));std::string tag,block,part,pre,tail;unsigned hd,hv;f>>tag>>offset>>parser.rows>>parser.structural>>parser.potential>>hd>>hv>>peak;need(bool(f)&&tag=="CP4V-VALIDATOR-1"&&hd<=1&&hv<=1,"state header","INVALID-CHECKPOINT");parser.header=hd;parser.have=hv;for(auto &v:sha.h){U x;f>>x;need(bool(f)&&x<=UINT32_MAX,"state word","INVALID-CHECKPOINT");v=x;}f>>block>>part;block=unhx(block);pending=unhx(part);for(auto&s:parser.previous){std::string a;f>>a;s=unhx(a);}f>>pre;f>>tail;need(f.eof()&&tail.empty()&&digest(pre),"state tail","INVALID-CHECKPOINT");need(offset<=UINT64_MAX/8&&block.size()==offset%64,"SHA state length","INVALID-CHECKPOINT");sha.Nl=uint32_t(offset<<3);sha.Nh=uint32_t(offset>>29);sha.num=block.size();memset(sha.data,0,sizeof sha.data);memcpy(sha.data,block.data(),block.size());need(hash(sha)==pre,"state prefix hash","INVALID-CHECKPOINT");need(parser.rows==parser.structural+parser.potential&&parser.structural<=parser.index.edges.size()&&parser.potential<=parser.index.potential,"state counts","INVALID-CHECKPOINT");need(parser.have==(parser.rows!=0)&&(!parser.rows||parser.header)&&pending.size()<=parser.index.maxline&&peak<=parser.index.maxline&&pending.find('\n')==pending.npos,"parser snapshot","INVALID-CHECKPOINT");}
 std::string save(){std::ostringstream s;s<<"CP4V-VALIDATOR-1 "<<offset<<' '<<parser.rows<<' '<<parser.structural<<' '<<parser.potential<<' '<<parser.header<<' '<<parser.have<<' '<<peak;for(auto v:sha.h)s<<' '<<v;auto enc=[](std::string x){return x.empty()?"-":hx(x);};s<<' '<<(sha.num?hx((unsigned char*)sha.data,sha.num):"-")<<' '<<enc(pending);for(auto&v:parser.previous)s<<' '<<enc(v);s<<' '<<hash(sha);return hx(s.str());}
};
bool same(const struct stat&a,const struct stat&b){return a.st_dev==b.st_dev&&a.st_ino==b.st_ino&&a.st_size==b.st_size&&a.st_mtim.tv_sec==b.st_mtim.tv_sec&&a.st_mtim.tv_nsec==b.st_mtim.tv_nsec&&a.st_ctim.tv_sec==b.st_ctim.tv_sec&&a.st_ctim.tv_nsec==b.st_ctim.tv_nsec;}
