 need(argc==5,"descriptor digest whole-bytes whole-sha required");auto begin=std::chrono::steady_clock::now();Index index(argv[1],argv[2]);U whole=std::stoull(argv[3]);std::string expected=argv[4];need(digest(expected)&&whole<=UINT64_MAX/8,"whole identity");
